{
  "a_sentences": [
    {
      "a_text": "Der Streit dreht sich um die hälftige Rentensperre des Versicherten ab 1. Januar 2023 wegen seiner Untersuchungshaft sowie um die daraus folgende Rückforderung von unrechtmässig bezogenen Rentenleistungen.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Vorinstanz ging davon aus, die Rentenkürzung könne erst ab 1. April 2023 greifen, weil die Haft länger als drei Monate gedauert habe.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Die Vorinstanz errechnete daraus eine Rückforderung von 2'508 Fr.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Nach Art. 21 Abs. 5 ATSG kann die Auszahlung von Erwerbsersatzleistungen bei einer Freiheitsstrafe oder -massnahme ganz oder teilweise eingestellt werden, ausgenommen sind Leistungen für die Angehörigen.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Gemäss Art. 25 ATSG ist ein unrechtmässig bezogener Betrag zurückzuerstatten.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Rentensperre setzt voraus, dass die Untersuchungshaft länger als drei Monate dauert.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht hält fest, dass die Rentenkürzung rückwirkend ab dem Folgemonat der Inhaftierung einsetzt, sofern die Haft mehr als drei Monate dauert.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt die Rückforderung von 5'016 Fr., da die Helsana Accidents SA dem Versicherten für die Zeit vom 1. Januar bis 31. Dezember 2023 zu hohe ganze Renten von insgesamt 15'048 Fr. statt der geschuldeten hälftigen Renten von 10'032 Fr. ausbezahlt hat.",
      "b_propositions": ["P8"]
    }
  ]
}
